   384	// buildDispatchRepoOptions dedupes but preserves the caller's order so each
   385	// source can pick its own order: the API path surfaces recent-first, and the
   386	// local-discovery fallback surfaces the current repo first.
   387	func buildDispatchRepoOptions(slugs []string) []huh.Option[string] {
   388		options := make([]huh.Option[string], 0, len(slugs))
   389		seen := make(map[string]struct{}, len(slugs))
   390		for _, slug := range slugs {
   391			if slug == "" {
   392				continue
   393			}
   394			if _, ok := seen[slug]; ok {
   395				continue
   396			}
   397			seen[slug] = struct{}{}
   398			options = append(options, huh.NewOption(slug, slug))
   399		}
   400		return options
   401	}
