    91	// readLastNLines reads the file as a stream and returns up to n trailing lines.
    92	// For typical log sizes this is fast enough; large files would benefit from a
    93	// reverse-seek implementation but the current logger rotates so files stay small.
    94	func readLastNLines(r io.Reader, n int) ([]string, error) {
    95		scanner := bufio.NewScanner(r)
