    98		for scanner.Scan() {
    99			line := scanner.Text() + "\n"
   100			if len(ring) < n {
   101				ring = append(ring, line)
   102			} else {
   103				ring = append(ring[1:], line)
   104			}
   105		}
   106		if err := scanner.Err(); err != nil {
   107			return nil, fmt.Errorf("scan log: %w", err)
   108		}
