   112	// followFile polls the log file for appended bytes. It exits cleanly when the
   113	// command's context is cancelled (Ctrl+C in a TTY).
   114	func followFile(ctx context.Context, w io.Writer, path string) error {
   115		f, err := os.Open(path) //nolint:gosec // path is .entire/logs/entire.log under repo root
   116		if err != nil {
